CREATE TABLE "products"
(
    "id"              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name"            varchar(100) NOT NULL,
    "barcode"         varchar(50) UNIQUE,
    "description"     text,
    "unit_of_measure" varchar(10)  NOT NULL,
    "created_at"      timestamp DEFAULT (now())
);

CREATE TABLE "inventory"
(
    "id"                   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "product_id"           int UNIQUE,
    "current_quantity"     decimal(12, 4) NOT NULL DEFAULT 0,
    "current_average_cost" decimal(10, 2) NOT NULL DEFAULT 0,
    "updated_at"           timestamp               DEFAULT (now())
);

CREATE TABLE "inventory_transactions"
(
    "id"               INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "product_id"       int,
    "transaction_type" varchar(10),
    "quantity"         decimal(12, 4) NOT NULL,
    "unit_value"       decimal(10, 2) NOT NULL,
    "transaction_date" timestamp DEFAULT (now()),
    "notes"            text
);

COMMENT ON COLUMN "products"."unit_of_measure" IS 'L, KG, UN, G, ML';

COMMENT ON COLUMN "inventory_transactions"."transaction_type" IS 'inflow or outflow';

ALTER TABLE "inventory"
    ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "inventory_transactions"
    ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;